bool decodeValue(const QJsonValue &input, NullableSafeInteger *output, QString *error) {
    if (input.isNull()) {
        output->value.reset();
    } else {
        SafeNonNegativeInteger decoded;
        if (!decodeValue(input, &decoded, error)) return false;
        output->value = std::move(decoded);
    }
    return true;
}
