bool decodeValue(const QJsonValue &input, Project *output, QString *error) {
    if (!input.isObject()) return fail(error, QStringLiteral("expected object"));
    const auto object = input.toObject();
    const QSet<QString> allowed{QStringLiteral("id"), QStringLiteral("name"), QStringLiteral("root")};
    for (auto it = object.begin(); it != object.end(); ++it) if (!allowed.contains(it.key())) return fail(error, QStringLiteral("unknown object field"));
    if (!object.contains(QStringLiteral("id"))) return fail(error, QStringLiteral("missing required field"));
    if (!decodeValue(object.value(QStringLiteral("id")), &output->id, error)) return false;
    if (!object.contains(QStringLiteral("name"))) return fail(error, QStringLiteral("missing required field"));
    if (!decodeValue(object.value(QStringLiteral("name")), &output->name, error)) return false;
    if (!object.contains(QStringLiteral("root"))) return fail(error, QStringLiteral("missing required field"));
    if (!decodeValue(object.value(QStringLiteral("root")), &output->root, error)) return false;
    return true;
}
QJsonValue encodeValue(const Project &value) {
    QJsonObject output;
    output.insert(QStringLiteral("id"), encodeValue(value.id));
    output.insert(QStringLiteral("name"), encodeValue(value.name));
    output.insert(QStringLiteral("root"), encodeValue(value.root));
    return output;
}

